"""Cross-check: phone patterns generated by logic.js must decode back to the same code with the
library's raw decoder (independent implementation). Run after `node tools/test_logic.js`."""
import json, os, sys
sys.path.insert(0, os.path.dirname(__file__))
from build_library import decode_raw, convert, pd_bits

pats = json.load(open(os.path.join(os.path.dirname(__file__), "patterns.json")))
expect = {"NEC-4-8": "NEC-4-8", "NEC-586-F": "NEC-586-F", "ONKYO-BF-1234": "ONKYO-BF-1234",
          "SAMSUNG-707-2": "SAMSUNG-707-2", "SONY-1-15-2-C": "SONY-1-15-2-C", "PANASONIC-8-3D": "PANASONIC-8-3D"}
for code, want in expect.items():
    got = convert(*decode_raw(pats[code]))[0]
    assert got == want, (code, got)
g = pats["GREE"]
first = pd_bits(g, 2, 32, 620, 540, 1600)
second = pd_bits(g, 2 + 70 + 2, 32, 620, 540, 1600)
assert " ".join(f"{x:02X}" for x in first + second) == "39 09 20 50 00 40 00 00"
assert decode_raw(g) is None  # Gree is not mistaken for NEC
print("patterns OK")
